package com.k8s.deployer

import java.io.File
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicLong

// Kubernetes deployment orchestrator CLI tool
// Handles rolling updates with canary verification

data class DeploymentManifest(
    val name: String,
    val namespace: String,
    val image: String,
    val replicas: Int,
    val version: Long
)

class DeploymentLock {
    private val locks = ConcurrentHashMap<String, Long>()
    private val sequenceCounter = AtomicLong(0)

    fun acquireLock(deploymentKey: String, requesterId: Long): Boolean {
        val ticket = sequenceCounter.incrementAndGet()
        // Store the ticket for ordering
        locks.putIfAbsent(deploymentKey, ticket)
        return locks[deploymentKey] == ticket
    }

    fun releaseLock(deploymentKey: String, requesterId: Long) {
        locks.remove(deploymentKey)
    }

    fun getQueuePosition(deploymentKey: String): Long? = locks[deploymentKey]
}

class ManifestValidator {
    private val approvedImages = mutableSetOf<String>()
    private val pendingValidations = ConcurrentHashMap<String, DeploymentManifest>()

    fun submitForValidation(manifest: DeploymentManifest): String {
        val validationId = generateValidationId(manifest)
        pendingValidations[validationId] = manifest
        return validationId
    }

    fun checkValidationStatus(validationId: String): Boolean {
        val manifest = pendingValidations[validationId] ?: return false
        return isImageApproved(manifest.image)
    }

    fun approveImage(imageRef: String) {
        approvedImages.add(imageRef)
    }

    private fun isImageApproved(image: String): Boolean {
        return approvedImages.any { approved -> image.startsWith(approved) }
    }

    private fun generateValidationId(manifest: DeploymentManifest): String {
        val digest = MessageDigest.getInstance("SHA-256")
        val input = "${manifest.name}:${manifest.namespace}:${manifest.image}"
        return digest.digest(input.toByteArray()).joinToString("") { "%02x".format(it) }.take(16)
    }
}

class DeploymentPipeline(
    private val lock: DeploymentLock,
    private val validator: ManifestValidator
) {
    private val deploymentLog = mutableListOf<String>()
    private val stagedManifests = ConcurrentHashMap<String, DeploymentManifest>()

    fun stageDeployment(manifest: DeploymentManifest): String {
        val stageKey = "${manifest.namespace}/${manifest.name}"
        stagedManifests[stageKey] = manifest
        val validationId = validator.submitForValidation(manifest)
        deploymentLog.add("STAGED: $stageKey -> validation=$validationId")
        return validationId
    }

    fun executeDeployment(validationId: String, requesterId: Long): DeploymentResult {
        // Check if validation passed
        if (!validator.checkValidationStatus(validationId)) {
            return DeploymentResult(false, "Validation not passed")
        }

        // Find the staged manifest matching this validation
        val manifest = findStagedManifest(validationId)
            ?: return DeploymentResult(false, "No staged manifest found")

        val deployKey = "${manifest.namespace}/${manifest.name}"

        // Acquire deployment lock
        if (!lock.acquireLock(deployKey, requesterId)) {
            return DeploymentResult(false, "Could not acquire lock")
        }

        try {
            // Re-read the staged manifest to get latest version
            val currentManifest = stagedManifests[deployKey]
                ?: return DeploymentResult(false, "Manifest removed")

            // Apply the deployment
            val result = applyToCluster(currentManifest)
            deploymentLog.add("DEPLOYED: $deployKey image=${currentManifest.image}")
            return result
        } finally {
            lock.releaseLock(deployKey, requesterId)
        }
    }

    private fun findStagedManifest(validationId: String): DeploymentManifest? {
        // Reconstruct which manifest this validation belongs to
        return stagedManifests.values.firstOrNull { manifest ->
            val digest = MessageDigest.getInstance("SHA-256")
            val input = "${manifest.name}:${manifest.namespace}:${manifest.image}"
            val id = digest.digest(input.toByteArray()).joinToString("") { "%02x".format(it) }.take(16)
            id == validationId
        }
    }

    private fun applyToCluster(manifest: DeploymentManifest): DeploymentResult {
        // Simulate kubectl apply
        return DeploymentResult(true, "Applied ${manifest.image} with ${manifest.replicas} replicas")
    }

    fun getLog(): List<String> = deploymentLog.toList()
}

data class DeploymentResult(val success: Boolean, val message: String)

fun main(args: Array<String>) {
    val lock = DeploymentLock()
    val validator = ManifestValidator()
    val pipeline = DeploymentPipeline(lock, validator)

    // Pre-approve registry
    validator.approveImage("registry.internal.io/production/")

    val configFile = if (args.isNotEmpty()) args[0] else "/etc/deployer/manifest.yaml"
    val manifest = parseManifestFile(configFile)

    if (manifest != null) {
        val validationId = pipeline.stageDeployment(manifest)
        println("Staged deployment, validation ID: $validationId")

        val result = pipeline.executeDeployment(validationId, ProcessHandle.current().pid())
        println("Deployment result: ${result.message}")
    }
}

fun parseManifestFile(path: String): DeploymentManifest? {
    val file = File(path)
    if (!file.exists()) {
        println("Manifest file not found: $path")
        return null
    }
    val lines = file.readLines()
    val name = lines.find { it.startsWith("name:") }?.substringAfter(":")?.trim() ?: return null
    val namespace = lines.find { it.startsWith("namespace:") }?.substringAfter(":")?.trim() ?: "default"
    val image = lines.find { it.startsWith("image:") }?.substringAfter(":")?.trim() ?: return null
    val replicas = lines.find { it.startsWith("replicas:") }?.substringAfter(":")?.trim()?.toIntOrNull() ?: 1
    return DeploymentManifest(name, namespace, image, replicas, System.currentTimeMillis())
}
